  "世界观": {
    "类型": "科幻 × 奇幻",
    "核心要素": [
      "虚数之树：将星系视为节点，虚数力量隔绝其间，星神与领使可穿越",
      "星穹列车：开拓命途星神阿基维利造轨星际交通工具，用于探险连接多星球",
      "星核：由星神散布，带来灾厄与裂界，是各地剧变根源",
      "命途：由星神掌控的存在哲学，每条命途代表一种意志，开启即不可逆"
    ],
    "星神与其命途": [
      {"星神":"阿基维利","命途":"开拓","象征":"探索与连接"},
      {"星神":"纳努克","命途":"毁灭","象征":"混沌与反物质"},
      {"星神":"岚","命途":"巡猎","象征":"狩猎与秩序"},
      {"星神":"克里珀","命途":"存护","象征":"守护与筑城"},
      {"星神":"博识尊","命途":"智识","象征":"知识与演算"},
      {"星神":"药师","命途":"丰饶","象征":"治愈与繁衍"},
      {"星神":"希佩","命途":"同谐","象征":"集体与和谐"},
      {"星神":"Ⅸ","命途":"虚无","象征":"空无与遗忘"}
    ]
  }
}

