entries.content:
{
  "简介": {
    "名称": "永恒之地（翁法罗斯）",
    "特征": [
      "「智识」「记忆」「毁灭」三重命途交汇之地",
      "只能通过忆庭之镜显现，暗示至少三位具备令使能力者曾存在",
      "外界无法直接观测，当地人信仰泰坦，不认星神概念",
      "黑塔与螺丝咕姆研究认为其为遗留的帝皇权杖"
    ]
  }
}
{
  "历史": {
    "轮回结构": "泰坦→灾厄降临→英雄收火种→半神晋升→再创世",
    "时代": ["启蒙世","造物世","黄金世","纷争世","幻灭世"],
    "泰坦分工": {
      "编织命运": 赐予时空秩序，
      "开辟天地": 创造山海，
      "捏塑生灵":生成万物，
      "引渡灾祸":掌控毁灭
    }
  }
}
{
  "剧情": [
    {
      "任务": "落木逐火英雄纪",
      "内容": "开拓者与丹恒来到翁法罗斯，协助黄金裔回收「纷争之泰坦」尼卡多利的火种。"
    },
    {
      "任务": "门扉之启，王座之终",
      "内容": "白厄未通过纷争试炼，经过恐惧挑战后成为新的纷争半神。盗火行者出没，瑟西斯与欧洛尼斯被杀。开拓者与黄金裔合力击败盗火行者，守护火种。"
    },
    {
      "任务": "走过安眠地的花丛",
      "内容": "开拓者接受岁月试炼后，参与公民大会决定是否继续逐火之旅。遐蝶与开拓者寻找死亡泰坦塞纳托斯遗躯，遐蝶通过试炼，成为死亡半神，并带回火种。白厄交出理性火种。"
    },
    {
      "任务": "在黎明升起时坠落",
      "内容": "阿格莱雅自愿牺牲以退场，白厄继任圣城领导。众人进入晨昏之眼击败天空泰坦艾格勒，风堇留下支撑天空。赛飞儿守护刻法勒圣城，牺牲为假火种。盗火行者袭击，多位黄金裔为回收火种牺牲。白厄和众人抵达创世涡心，准备再创世。"
    }
  ]
}
黄金裔：流淌着黄金之血的英雄们，他们为了拯救翁法洛斯，踏上了收集火种，再创世的旅途。

