entries.content:
{
  "仙舟罗浮": {
    "地理与文明概况": {
      "位置与功能": "作为仙舟联盟的六大座舰之一，“罗浮”漂航于无尽星海，承担巡猎丰饶孽物、维护生态、贸易交流等多重使命。",
      "城市风貌": "丝绸朋克外观：融合古典徽派结构与现代科技元素，视觉上既有传统宫殿风韵，又兼具机械与蒸汽感。商业与文化中心：寰宇商人枢纽，商铺、展馆、交流区充满活力，时间沉淀于此、故事层层交织。",
      "组织机构": "五脉自治：持明一族获赠“方壶”仙舟后自治；罗浮设有完整的六司体系，包括云骑军、太卜司、丹鼎司、工造司、天舶司与地衡司。云骑军领袖为景元将军（神策将军），支援列车组处理外部危机与星核事件。"
    },
    "核心剧情脉络": {
      "星核危机爆发": [
        "列车组接卡芙卡邀请前往罗浮处理“星核之乱”。",
        "景元将军委派逮捕身负星核的卡芙卡与刃。",
        "卡芙卡说明列车组是解除灾害关键，星核已注入“建木”遗迹。",
        "景元命玉卜司符玄与云骑军监视丹鼎司封印区，列车组前往工造司击退“丰饶萱鹿”。"
      ],
      "丹鼎司密战与幻胧现世": [
        "云骑军与“药王秘传”在丹鼎司爆发激战，毒雾蔓延。",
        "列车组助力关闭丹炉，冲突升级。",
        "幻胧伪装“停云”出现，并试图借建木摧毁罗浮。"
      ],
      "鳞渊境最终对决": [
        "丹恒在进入鳞渊境途中显露“饮月君”身份（持明龙尊觉醒）。",
        "景元借助丹恒之力击断建木根修，打开鳞渊境路径。",
        "幻胧借建木重塑肉身并企图控制景元。",
        "丹恒用长枪击断幻胧控制链，景元召唤“神君”协力重创幻胧，使其逃离并与建木脱钩。",
        "景元重伤昏迷，局势暂稳。"
      ],
      "善后仪式与外交交锋": [
        "罗浮为伪装“停云”的遇难者举行“慰灵奠仪”。",
        "列车组与云骑军共同返回，继续星海旅程。"
      ],
      "演武仪典与联盟重建": [
        "景元举办“星天演武仪典”，邀请列车组与联盟各仙舟代表参加，用以重建信任与展示实力。",
        "场地为改造后的“竞锋舰”。",
        "朱明将军怀炎、曜青将军飞霄等高层出席，协助咨询景元在危机中的表现。",
        "呼雷被救回公开签字，联盟形势趋于稳定。",
        "景元通过演武展示军事与外交威望。",
        "景元徒弟彦卿胜出，列车组成员卢卡促成《仙舟‘罗浮’—贝洛伯格互惠贸易协定》。"
      ]
    },
    "关键词总结": {
      "地理": "丝绸朋克风格，古典＋机械，商贸与文化中心，设有丹鼎司、太卜司/云骑军驻地",
      "剧情": "星核危机发现→联手审讯卡芙卡→对抗幻胧于持明殿→慰灵仪式→仙舟高层外交→演武仪典巩固联盟"
    }
  }
}

