entries.content:
{
  "星球": "匹诺康尼",
  "原始用途": "星际和平公司流放犯人之地",如今已是度假胜地，美梦之都。

  "地理环境": {
    "物理外貌": "遍布球形“球笼”工作舱遗迹，后被改造成梦境载具",
    "核心设施": [
      "“白日梦”酒店：覆盖整星球的巨大酒店，也是通往梦境的入口",
      "十二梦境时分：对应十二时辰的梦境区，各有独特主题场景"
    ],
    "梦境分区": {
      "黄金的时刻": "豪华繁华的午夜梦境，珍宝云集，现正在翻新",
      "子夜的时刻": "存在灵异传闻，令人生畏",
      "安谧的时刻": "监狱梦境，关押重刑梦想犯，深藏危险",
      "朝露的时刻": "家族办公地点，政务聚集",
      "黎明的时刻": "工厂区，生产梦境商品，地下管道迷宫",
      "烫金的时刻": "金融中心，梦境经济要塞",
      "太阳的时刻": "文化与历史展示区，大剧院、图书馆、大学等",
      "绿洲的时刻": "梦中公园，午后悠闲之地",
      "热砂的时刻": "广阔原野与赛事中心，热情狂野",
      "薄暮的时刻": "购物天堂与拍卖中心",
      "蓝调的时刻": "梦泡海舞会区，豪华游轮活动场",
      "星辰的时刻": "机动球及竞技赛场"
    },
    "交通文化": {
      "球笼": "沿梦境城市的彩色轨道滚动，演变自囚笼",
      "球笼竞速": "当前最热门梦境运动，以“仓鼠球骑士”等角色闻名"
    }
  },

  "人文文化": {
    "社会人口": [
      "人类、天环族、皮皮西人及智械共同组成",
      "天环族：心灵感应、艺人领袖，多为文化家族成员",
      "皮皮西人：智慧勤劳，操控经济与建设",
      "智械：有机与无机交织，对梦境表现出高度好奇"
    ],
    "家族体系": {
      "五大家系": [
        "橡木家系（政治管理）",
        "苜蓿草家系（经济贸易）",
        "猎犬家系（安保守护）",
        "鸢尾花家系（文化娱乐）",
        "隐夜鸫家系（梦境建设）"
      ],
      "梦主": "歌斐木，橡木家系成员，幕后精神控制者",
      "家族职能": [
        "庆典组织、梦境建设、市场运行、知识传播、安全维护"
      ]
    },
    "信仰与象征": {
      "星神信仰": "匹诺康尼居民信仰“同谐”星神希佩，倡导包容与共鸣",
      "谐乐大典": "每琥珀纪举办，歌颂同谐精神，多派系派代表参与"
    },
    "文化象征": {
      "球笼": "梦境交通载具，也象征囚犯记忆的解放",
      "苏乐达": "气泡饮料，梦境能量来源与精神象征",
      "《钟表小子》动画": "寓教于乐的本地文化标志，暗含历史与教育意义"
