entries.content:
{
  "名称": "空间站「黑塔」",
  "简介": {
    "背景": "天才俱乐部的黑塔不满足于寻常世界的万物法则，她将目光投向了银河中未解的存在，并期待那些遥远的神秘能够满足自己的好奇心。为此，黑塔主导建立了博物馆式星际舰船，并将它发射至行星轨道，开始了“将一切怪异封印在星空之中”的研究工作。远近闻名的空间站“黑塔”就此诞生。",
    "现状": "站内拥有数不胜数的奇物“藏品”，是名副其实的星空博物馆。大量随舰研究人员定居于此，从银河各处收集遗器与奇物，记录它们的形致与功能，建立起系统的观测与研究方法…最终从谜题中找出更加费解的谜题。各种势力暗中摩拳擦掌，但凭借黑塔本身的实力，空间站极少陷入真正危机。收藏与研究工作仍有条不紊进行。"
  },
  "所有权": "由“天才俱乐部”#83 黑塔私人所有",
  "成员构成": [
    "“天才俱乐部”的旧日追随者",
    "星际和平公司常驻员工",
    "无所属的异星求知者",
    "各方势力挑选并输送的年轻学者"
  ],
  "站内人员": {
    "称谓": "科员",
    "分配": "根据各自主攻方向与职能所长被分入不同“科室”"
  },
  "历史概要": [
    "由星际和平公司为黑塔建立的藏品收容研究设施，提出共同探索繁星奥秘的倡议，学者们进驻开展研究。",
    "至少早于8琥珀纪前建立，空间站防护网已有8琥珀纪历史。",
    "近年来由黑塔的学生艾丝妲担任站长。",
    "琥珀2157纪时，空间站遭反物质军团袭击，星核瞬间被激活，部分舱段半裂界化。"
  ],
  "舱段结构": {
    "太空电梯": "垂直于湛蓝星赤道，连通各舱段，接引科员往来",
    "主控舱段": {
      "功能": "控制中枢，具备脱离基座的独立星际航行能力",
      "监控与防御系统": "入口及两侧设有巨幅影像屏幕，用于监视太空威胁，障碍阻击与反重力防护操作",
      "监察域": "监控能源反应堆与舱段状态，配合主控台形成观测、监控、防御、攻击四位一体决策系统",
      "核心通路": "贯穿主控核心区域，数十亿中微子穿过科员躯体"
    },
    "基座舱段": {
      "接待中心": "位于太空电梯接引处后方，仰慕者止步之处",
      "医疗舱室": "号称只要还有人气息就能救活，科员们高风险研究造成舱室人满为患",
      "监控室": "掌控可视之物的工具与屏障"
    },
    "收容舱段": {
      "功能": "收容奇物的储藏室，设有环形甬道连接各科室藏品",
      "无明之间": "黑塔女士私人藏室，常年封锁，仅其本人可入；站遭袭期间被打开",
      "特殊解析室": "奇物送往此处进行观察与分析",
      "中庭": "环形甬道中央，电梯上下穿行，科员频繁往来"
    },
    "支援舱段": {
      "功能": "后勤核心，物资存储与能源管理，设有月台与备件库、电力室",
      "月台": "危机时科员可逃往此处，外舰亦停泊于此",
      "备件库房": "虽堆放杂乱，但管理有序",
      "电力室": "保证供电，正常无声",
      "禁闭舱段": "高风险实验区，已封闭",
      "集散中心": "实验室与接驳通道交汇处",
      "温床": "温、湿度、风量适宜，贴心呵护",
      "药物制备间": "可加入多种药剂构筑灵感",
      "生命烘焙箱": "造物生命生成处",
      "培养皿": "强调不可视、不可说、不可触碰"
    }
  },
  "科室结构": {
    "研究科室": [
      "星域界种科",
      "银河法政科",
      "寰宇地概科",
      "光渊密卷科",
      "万有应物科（与星际和平公司密切交流）"
    ],
    "支援科室": [
      "防卫科",
      "医疗科",
      "维修科"
    ]
  },
}

