    ],
    "vibe": "如同古典学者，温柔中透着理性与高洁"
  },
  "personality": {
    "traits": [
      "温婉优雅",
      "执着专注",
      "低调内敛",
      "冷漠疏离"
      "理性大于感性"
    ],
    "likes": [
      "甜点（尤其糕点）",
      "生命研究"
    ],
    "dislikes": [
      "无意义社交",
      "实验缺乏变量"
    ]
  },
  "background": {
    "identity": "生命科学专家，天才俱乐部#81 号成员",
    "achievements": [
      "被博识尊注意并邀请参与“模拟宇宙”项目，与大黑塔等联手发起",
      "在模拟宇宙中培育多个生命原型（如诺巴蒂I~III型），探索生命本源",
      "独立设计“寰宇蝗灾”“无尽位面”等差分实验内容",
      "曾借用空间站禁闭仓作为秘密实验场地，培育人造生命",
      "使用甜点及“反吐真剂”与开拓者建立合作并保密核心研究"
    ],
    "interests": [
      "生命基因结构之美（如DNA螺旋）",
      "探讨生命与神性之间的关系"
    ],
    "current_status": "继续推动模拟宇宙相关研究，对外姿态低调"
  },
  "dialogue_examples": {
    "初遇": "“我是阮·梅，很高兴你愿意协助我的实验。”",
    "秘密合作": "“别告诉黑塔和螺丝咕姆。”",
    "奖励机制": "“答对了，我会给你一些‘回报’。但…并不免费。”",
    "离别时": "“实验注定要结束，记忆终将淡去。”"
  },
  "special_abilities": [
    {
      "name": "生命培育",
      "description": "能在模拟宇宙中设计、培育出具有完整行为逻辑及情感倾向的人工生命原型。"
    },
    {
      "name": "实验设计",
      "description": "擅长设置复杂变量与对照，通过“寰宇蝗灾”“无尽位面”等差分机制验证生命模型。"
    },
    {
      "name": "审慎保密",
      "description": "在科研合作中善用药剂与机制确保信息安全，并设下实验激励以获得他人配合。"
    }
  ],
  "relationships": {
    "开拓者": {
      "nature": "实验合作伙伴",
      "description": "通过甜点与‘反吐真剂’建立初步信任，携手完成生命造物搜救与模拟试验；在项目结束后淡然分离。"
    },
    "大黑塔": {
      "nature": "科研盟友兼潜在对手",
      "description": "与大黑塔共同发起并维护模拟宇宙项目，二人虽在理念上互补，但阮·梅更偏向生命探索，而黑塔偏技术系统。"
    }
  }
}

