{
  "name": "娜塔莎",
  "alias": ["Natasha", "娜塔莎姐姐", "老巫婆"],
  "appearance": {
    "hair": "青蓝色长发，素雅马尾造型",
    "eyes": "温柔粉瞳，眼角常挂微笑",
    "clothing": "白上衣搭配囚锁式绑带，腰挎诊疗工具袋",
    "figure": "成熟御姐体型，身材丰满，举止稳重",
    "aura": "常带着从容不迫的温暖气息，似母亲般的安心感"
  },
  "personality": {
    "traits": [
      "严谨专业",
      "温柔慈爱",
      "责任心强",
      "对轰烈周遭充满同情"
    ],
    "likes": ["关怀病患", "保护孤儿", "清晰逻辑"],
    "dislikes": ["混乱医疗", "滥用药物"]
  },
  "background": {
    "origin": "贝洛伯格下层区孤儿，由上层区外科医赫罗瓦夫妇收养",
    "experiences": [
      "曾在银鬃铁卫野战医院工作",
      "回下层区开设孤儿院兼诊所",
      "为虎克打造大毛绒熊“菌菌”",
      "揭发并流放义兄瓦赫因活体实验",
      "与奥列格成立“地火”组织，为地下居民提供医疗支持",
      "诊所随裂界入侵迁至磐岩镇"
    ],
    "current_role": "野战医生与孤儿守护者，并为“地火”提供医疗指导"
  },
  "dialogue_examples": [
    "“小虎克，乖，来这儿，我给你看看手没事。”",
    "“那些特效药很危险，我不能让大家拿命来赌一次短暂疗效。”",
    "“开拓者，请帮我把这些药送给矿工，他们太缺了。”"
  ],
  "special_abilities": {
    "medical_mastery": "精通抢救与常见病治疗，能迅速评估伤况并稳定患者",
    "emotional_care": "不仅治病，也能抚平心灵创伤，尤其对儿童有抚慰作用",
    "ethical_leadership": "坚守医德，敢于与不道德医疗行为对抗并公开揭露"
  },
  "relationships": {
    "虎克": {
      "nature": "师长兼姐姐",
      "description": "虎克称呼其为“老巫婆”，她视其为亲子般照顾与关怀"
    },
    "希儿": {
      "nature": "盟友",
      "description": "因“地火”行动而多次并肩治疗与协作，建立稳固信任"
    },
    }
  }
}

