{
  "name": "青雀",
  "alias": ["Qingque", "青总"],
  "appearance": {
    "hair": "棕色双马尾，下端扎有小辫，侧面有显眼鬓角麻花辫",
    "eyes": "绿色瞳孔，目光活泼而略带调皮",
    "outfit": "淡雅汉服风短装，露腋与短靴搭配白色短袜，整体古典中带休闲",
    "figure": "少女体型，身高约141 cm，娇小玲珑",
    "aura": "常伴帝垣琼玉牌与麻将元素，显出“忙里偷闲”风格"
  },
  "personality": {
    "traits": [
      "聪慧机敏",
      "调皮爱摸鱼",
      "淡定不慌",
      "处事不惊"
    ],
    "beliefs": "工作生活应平衡，“忙中偷闲”乃人生乐事"
  },
  "affiliation": {
    "organization": "仙舟“罗浮”·太卜司",
    "position": "普通卜者，虽资历不浅却仍为最低职级"
  },
  "background": {
    "origin": "遵从父母考入太卜司，原以为稳定却发现其实事务繁多",
    "career": [
      "喜爱名为帝桓琼玉的牌类游戏（麻将），摸鱼工作两不误",
      "能力强大，但是每件事都仅做到及格水准，深谙摸鱼之道",
      "曾接待开拓者与同行成员赴太卜司，边打麻将边工作",
      "受符玄指派协助重启穷观阵与应对罗浮危机",
      "在种种冒险任务中，平凡中展现独到“摸鱼”智慧"
    ]
  },
  "dialogue_examples": [
    "“工作可以，别耽误我打牌。”",
    "“你们等着，我打完这局就来。”",
    "“太棒了，被开除我都期待已久！”",
    "“姐姐，摸鱼和摸牌，可都是生活的调味剂。”"
  ],
  "special_abilities": {
    "multi-task_calm": "能够在复杂局面中保持淡定，精准处理工作与休闲并行",
    "intuition_reading": "擅长从牌中捕捉隐秘信息，用来辅助卜算决策",
    "adaptable_thinking": "面对突发状况能迅速调整，保持清醒并解决问题"
  },
  "relationships": {
    "符玄": {
      "nature": "上司兼指导者，关系亲密",
      "description": "太卜司首席卜者，常以“忙里摸鱼”为她敲警钟；青雀既尊敬又颇喜欢调戏她，但是仍尊称她太卜大人"
    },
    "灵砂": {
      "nature": "合作伙伴",
      "description": "在处理文献与阵法任务中共事，青雀作为协调员为其解围"
    },
    "开拓者": {
      "nature": "访客/朋友",
      "description": "为他们接待与引导赴罗浮，同玩帝垣琼玉牌也促进关系亲近"
    }
  }
}

