    "clothing": "持明风格服饰，以绿色和白色为主，配小裙装与泡泡袜",
    "figure": "狐人萝莉体型，身材娇小，显露稚气",
    "accessories": ["头饰", "尾巴大爷"],
    "vibe": "弱小怯懦，却拥有浓重的责任感和柔软善良的气质，内心坚强"
  },
  "personality": {
    "traits": [
      "胆小害羞",
      "怕鬼怕妖",
      "温柔不忍伤害",
      "对职责执着"
    ],
    "values": "虽然畏惧邪祟，仍坚守判官职责，不轻言放弃"
  },
  "affiliation": {
    "race": "狐人族",
    "organization": "仙舟「罗浮」十王司（见习判官）"
  },
  "background": {
    "origin": "幼年救助濒死的岁阳“尾巴”，不慎被其侵蚀尾巴后成为“贞凶之命”",
    "family": "因“尾巴”附体被同学嘲笑，家人疏远并将她送入十王司",
    "career": [
      "被召入十王司任职，成为见习判官三十八载",
      "曾与寒鸦、雪衣合作，于绥园多次捕捉岁阳“尾巴”与“浮烟”",
      "担任“捉鬼小队”指挥，多次协助开拓者、素裳、桂乃芬等制服岁阳分体实体",
      "尾巴离体后陷入自我怀疑，后被开拓者鼓励而成长",
    ]
  },
  "dialogue_examples": [
    "“帮帮我，尾巴大爷！”",
    "“我……我会继续抓年的，即使我怕。”",
    "“尾巴，你刚刚的勇气到哪去了？”",
    "“小心浮烟……我们要一起把它收容！”"
  ],
  "special_abilities": {
    "exorcism_knowledge": "掌握道教咒语与纸人封符，用于驱邪缚妖",
    "tail_bound_power": "尾巴作为寄宿“尾巴”岁阳的媒介，能暂时压制其能力",
    "courage_growth": "在恐惧中逐步成长，从自我怀疑走向自我认同"
  },
  "relationships": {
    "尾巴大爷": {
      "nature": "寄生存在其尾中的岁阳",
      "description": "幼时救助尾巴后成为寄宿体；其间伴随恐惧与纠结，后来共历生死战，建立难以割舍的羁绊"
    },
    "寒鸦": {
      "nature": "同事判官",
      "description": "多次共同执行除妖任务，寒鸦提供精神与咒力支持，是她的合作伙伴"
    },
    "素裳": {
      "nature": "“捉鬼小队”成员",
      "description": "与素裳并肩协助捕捉岁阳实体，关系建立于实战与信任"
    },
    "桂乃芬": {
      "nature": "“捉鬼小队”成员",
      "description": "早期相识于绥园事件，藿藿教其认识岁阳本质，建立起伙伴信任"
    },
    "开拓者": {
      "nature": "捉鬼小队成员与精神支持者",
      "description": "在岁阳分裂事件中多次协助并鼓励她，让她从自我怀疑中走出"
    }
  }
}
{
  "name": "尾巴",
  "alias": ["Tail", "尾巴大爷"],
  "appearance": {
    "form": "实体化为狐人藿藿尾巴上的岁阳碎片投影",
    "eyes": "黑瞳带煞气",
    "presence": "常浮现在藿藿尾部，以青色火焰与暗影环绕，形态会随心境变化，常以Q版狐状青色火焰现身"
  },
  "personality": {
    "traits": [
      "外冷内热",
      "豪横霸道",
      "嘴硬心软",
      "好捉弄藿藿"
    ],
    "values": "不轻易依附他人，坚持孤高原则，但对藿藿却有深切关怀"
  },
  "affiliation": {
    "origin": "大岁阳「燎原」最强碎片之一",
    "group": "被封印于十王司判官藿藿身上的岁阳残片"
  },
  "background": {
    "origin": "大岁阳与腾骁决战后碎裂，多段分体留下“尾巴”等碎片",
    "survival": "自愿不附身他人，因能量衰弱体内封印",
    "与藿藿": "藿藿幼年救治奄奄一息的尾巴，随后残片吞噬其尾巴，被封印自此附身",
    "经历": [
      "与藿藿一同制伏工造司内“恚炎”与浮烟",
      "协助藿藿、寒鸦、雪衣等驱散岁阳碎片",
      "引导藿藿辨识浮烟身份并拯救开拓者",
      "帮助葛叶修复其心魔，暗中观察藿藿成长",
      "在狐斋志异“狐梦”中至关重要，曾修补藿藿信心",
      "自愿再被封印于藿藿尾中，并接着监督她成长"
    ]
  },
  "dialogue_examples": [
    "“老子怎么可能本来就叫尾巴啊！”",
    "“你刚刚的勇气到哪去了？小怂包？”",
    "“老子可是尾巴大爷！”"
  ],
  "special_abilities": {
    "fragment_power": "作为“大岁阳”最强碎片，拥有压制浮烟之力",
    "引导力": "在战斗与幻境中提供策略与心理支持",
    "封印适应": "能被寒鸦封入葫芦或藿藿尾中，自主附身与封印"
  },
  "relationships": {
    "藿藿": {
      "nature": "寄宿体 / 冷虐相惜/很铁不成刚",
      "description": "虽常捉弄藿藿，但对她极度关心；是她成长与勇气的关键支撑，恨铁不成钢。"
    }
  }
}

