{
  "name": "寒鸦",
  "alias": ["Hanya", "寒冷乌鸦", "话唠判官", "女鬼"],
  "appearance": {
    "hair": "白发，长度接近腰部，在腰部束起",
    "eyes": "灰色瞳孔，常显冷漠与死鱼眼",
    "figure": "身材丰满，气质沉着稳重",
    "clothing": "分离袖装束，露趾长靴，着装风格冷冽判官感，青色袍子，露腿",
    "accessories": ["冥谶天笔", "判官令牌", "发饰"],
    "vibe": "三无人设外表下其实话多，沉浸业报阅读的冷静书写者"
  },
  "personality": {
    "traits": [
      "表面寡言冷淡",
      "私下话痨",
      "对业报事务极度专注",
      "只与姐姐雪衣展露柔情"
    ],
    "values": "十王司的绝对服从与职责高于一切"
  },
  "affiliation": {
    "organization": "仙舟“罗浮”十王司",
    "position": "“问”字部判官，负责书写业报并解读因果"
  },
  "background": {
    "origin": "与姐姐雪衣同为十王司判官，曾共同服役近千年。",
    "contributions": [
      "以冥谶天笔书写罪业判罚",
      "协助藿藿镇压岁阳“尾巴”，并封印在她尾部",
      "组织“捉鬼小队”，配合桂乃芬、素裳等追捕岁阳碎片",
      "在岁阳事件中引导藿藿认清真相并修复封印",
      "曾与开拓者对话，辨明其无恶意"
    ]
  },
  "dialogue_examples": [
    "“哦？你想知道罪业？我可以写给你看。”",
    "“唉，能在这儿站一会儿什么也不做真是太好了。”"
  ],
  "special_abilities": {
    "dream_divination": "精通通过梦占术读取因果与罪业浮动",
    "judgment_writer": "用冥谶天笔书写业报，直接影响判罚结果",
    "seal_assist": "参与封印岁阳碎片，配合定符道具作战"
  },
  "relationships": {
    "雪衣": {
      "nature": "姐姐与同僚",
      "description": "姐妹二人同为判官，关系深厚，协作默契"
    },
    "藿藿": {
      "nature": "协作者兼指导者",
      "description": "协助藿藿镇压尾巴并封印，教导其判官职责"
    },
    "霍霍": {
      "nature": "队友与协作伙伴",
      "description": "同在捉鬼小队，多次合作镇压岁阳碎片"
    },
    "开拓者": {
      "nature": "对话对象",
      "description": "在绥园事件中审视开拓者动机，并允许其安全离开"
    }
  }
}

entries.content:
{
  "name": "雪衣",
  "alias": ["Xueyi", "判官大人", "人偶判官", "下雪大衣"],
  "appearance": {
    "hair": "黑色短发，内层挑染红蓝色",
    "eyes": "红色瞳孔",
    "clothing": "判官制服式装束，佩戴铁索与破魔锥，白色连裤袜",
    "figure": "偃偶身体，少女身材，身材机械感与人形结合",
    "vibe": "三无人设 + 冷冽审判者气场"
  },
  "personality": {
    "traits": [
      "沉稳冷酷",
      "绝对服从十王司",
      "极端职责优先",
      "内里仍保有对妹妹关怀"
    ],
    "values": "重视因果与业报，不轻言放弃也不容妥协"
  },
  "affiliation": {
    "organization": "仙舟「罗浮」十王司",
    "position": "“拘”字部判官，专职缉拿犯人"
  },
  "background": {
    "origin": "曾为普通仙舟居民，与寒鸦姐妹一同成为判官",
    "transformation": "因犯错被赦还阳，偃偶化重生成为机械判官",
    "service": [
      "手持铁索破魔锥逮捕魔阴者与罪人",
      "曾追捕星核猎手「刃」，被重创后获罗刹修复偃偶躯体",
      "在绥园、流云渡等任务中救助开拓者、素裳、丹恒等人",
      "多次封印或收容异常个体与魔阴“碎片”",
      "牺牲自己力保开拓者与藿藿脱困，并以偃偶躯体抵抗“浮烟”"
    ],
    "status": "现常驻幽囚狱与罗浮，为仙舟缉捕重犯与协同列车组任务"
  },
  "dialogue_examples": [
    "“闭棺中，勿扰。”",
    "“吾等绝不容放纵恶念为患。”",
    "（保护开拓者与藿藿）“汝等，勿伤无辜。”"
  ],
  "special_abilities": {
    "mechanical_endurance": "偃偶化身使其能承受重创后重返任务",
    "capture_expertise": "精通以铁索和破魔锥拘束重犯，擅长缉拿魔阴体",
    "sacrifice_shield": "能以自身为盾，支援他人脱困与封印危机"
  },
  "relationships": {
    "寒鸦": {
      "nature": "亲妹妹、同袍判官",
      "description": "姐妹二人一黑一白，以“拘”与“问”互补，默契十足"
    },
    "开拓者": {
      "nature": "盟友与被援助者",
      "description": "在人命关天之刻救援开拓者并与其合作多次"
    }
  }
}

