      "赴艾普瑟隆星系任歌者，声名远播"
    ],
    "career_highlight": [
      "因颈部受伤贴饰掩盖疤痕后重返舞台",
      "受邀参加匹诺康尼“谐乐大典”，却因原因失声",
      "与开拓者在梦境中相遇，以“同谐”能力助其稳定梦境",
      "在“太一之梦”事件后，带领人们脱离虚梦，并继续守护匹诺康尼"
    ]
  },
  "dialogue_examples": [
    "“让我们把翅膀借给彼此。”",
    "“这片银河，容得下任何可能性。”",
    "“谢谢你让我重新听见‘同谐’的声音。”"
  ],
  "special_abilities": {
    "concert_resonance": "通过“同谐”力量，将歌声共鸣至万界众生",
    "dream_guidance": "在梦境中稳定听众情绪，帮助他们自我觉醒",
    "healing_voice": "声音能抚慰创伤，恢复精神力量"
  },
  "relationships": {
    "星期日": {
      "nature": "亲哥哥",
      "description": "兄妹并肩成长，因理念不同一度对立，后在危机中重修信任"
    },
    "开拓者": {
      "nature": "盟友",
      "description": "在梦境中协助开拓者，从此建立信赖关系，并在多次事件中互相扶持"
    }
  }
}

