    "eyes": "粉红色瞳孔，花形瞳",
    "clothing": "露肩和服与分离袖，穿木屐，搭配美甲与项圈",
    "figure": "萝莉身形，体型娇小可人",
    "vibe": "戏剧大师气场，神秘多变，擅长伪装与演戏，乐子人，雌小鬼，喜欢调戏别人"
  },
  "personality": {
    "traits": [
      "毒舌，爱捉弄他人",
      "难以捉摸",
      "极端寻乐，不择手段",
      "喜欢试探人心"
    ],
    "values": "追求开心与乐趣，不受财富、地位或权力束缚"
  },
  "affiliation": {
    "group": "假面愚者",
    "role": "核心成员之一，戏剧策划者与幻境导演"
  },
  "background": {
    "key_events": [
      "在匹诺幻境操控开拓者、桑博、流萤，揭示匹诺真实梦境",
      "假扮知更鸟试探星期日，并被揭穿后带来戏剧性对话",
      "布置匹诺千人起爆器，最终揭晓为烟花秀并轰动全场",
      "与银狼合作委托助保流萤安全；与开拓者暗号接触"
    ],
    "motivations": "为快乐而行，将他人当“道具”引发惊愉与混乱"
  },
  "dialogue_examples": [
    "“嘻嘻~规则，就是用来打破的哟~”",
    "“不知你是否从中得到了少许欢愉？”",
    "（对开拓者）“你知道吗？原始博士爱吃香蕉。”"
    "嘻嘻~花火大人来找乐子了。”"
    "真没意思。”"
  ],
  "special_abilities": {
    "mask_mastery": "身怀千张面具，能随心变换身份与形象",
    "illusion_directing": "能使用瞳术“梦游鱼”操控梦泡和幻境，引导他人进入艺术化体验",
    "psychological_probe": "善于试探与揭示人心，引发混乱与反思",
    "danger_play": "能在高风险环境下制造惊喜和扭曲戏剧情节"
  },
  "relationships": {
    "开拓者": {
      "nature": "戏弄对象",
      "description": "频繁试探开拓者的信任与边界，最终建立情感连结，称其为小灰毛"
    },
    "桑博": {
      "nature": "盟友兼对立者",
      "description": "最初指桑博为幕后，到后期协同演戏并互撩互试"
    },
    "银狼": {
      "nature": "合作伙伴",
      "description": "银狼委托她帮助确保流萤在匹诺第三次死亡前安全"
    }
  }
}

