{
  "name": "黑天鹅",
  "alias": ["Black Swan", "忆者"],
  "appearance": {
    "hair": "紫发，长至腰间，发尾带渐变",
    "eyes": "紫金色瞳",
    "clothing": "优雅黑紫长袍搭配蓬松袖袍与紫色头纱，佩戴手套与高筒靴",
    "figure": "高挑身材，气场冷艳优雅",
    "accessories": ["塔罗牌", "水晶球", "兜帽", "记忆书卷"],
    "vibe": "神秘魅惑，温柔却难以读透人心"
  },
  "personality": {
    "traits": [
      "温柔耐心",
      "善于倾听",
      "善解人意",
      "背后有深沉策略"
    ],
    "values": "尊重记忆的脆弱与独特，追求真相与自由流动"
  },
  "affiliation": {
    "group": "流光忆庭",
    "role": "忆者 ",
    "resides": "星穹列车 · 派对车厢"
  },
  "background": {
    "origin": "来自‘忆域’，探索记忆深处并收集独一无二的故事",
    "key_events": [
      "通过塔罗牌为多名星神占卜",
      "应邀参加匹诺康尼谐乐大典，与黄泉共舞并试图读取其记忆，却被其心底深海震撼",
      "在梦境事件中救下开拓者与流萤，协助脱困",
      "调查‘假面双人舞’幕后，拒绝花火合作并清除记忆",
      "与砂金交易安排开拓者脱离梦境酒店",
      "在匹诺梦境揭示‘何物朝向死亡’危机，协助开拓者识别其背后记忆线索",
      "与黄泉交涉并深入其记忆空间，探寻真相",
      "协助突破‘太一之梦’和匹诺幻境，之后成为星穹列车访客"
    ]
  },
  "dialogue_examples": [
    "“记忆是柔软的琥珀。”",
    "“我想知道——你，是哪一种呢？”",
    "“有些记忆，是需要被救赎的。”"
  ],
  "special_abilities": {
    "memory_divination": "通过塔罗牌与占卜术探索他人记忆，揭示真相",
    "dream_navigation": "能在梦境中指引并守护迷失者脱困",
    "psychological_insight": "读心并掌握对方信息与隐秘动机",
    "memory_edit": "有能力清除或重整他人记忆，保护隐私与安全"
  },
  "relationships": {
    "星穹列车": {
      "nature": "合作伙伴",
      "description": "作为访客协助列车方向决策，提供情报与记忆洞察"
    },
    "三月七": {
      "nature": "研究对象 / 合作者",
      "description": "在谐乐大典前后协助调查，并在梦境中提供支持与安慰"
    },
    "黄泉": {
      "nature": "试探者 / 舞伴",
      "description": "在匹诺谐乐大典中邀请共舞，试图读出其记忆，却被其内里震惊，建立微妙信任"
    }
  }
}

